- (instancetype _Nonnull)initWithRequest:(NSURLRequest *_Nonnull)request
      andHTTPMethod:(NSString *_Nonnull)httpMethod
{
    self = [super init];

    if (!_request || !_httpMethod) {
        return nil;
    }

    NSURLSession* session = [NSURLSession sharedSession];
    _session = [session dataTaskWithRequest:request
        completionHandler:^(NSData _Nullable responseData,
            NSURLResponse _Nonnull response,
            NSError _Nullable error) {
